<?php
require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/functions.php'; require_role(['admin','staff']);
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
$s=$pdo->prepare("SELECT COUNT(*) bills,COALESCE(SUM(total_amount),0) billed,COALESCE(SUM(total_amount-balance),0) collected,COALESCE(SUM(balance),0) outstanding,COALESCE(SUM(consumption),0) usage FROM bills WHERE DATE(created_at) BETWEEN ? AND ?");$s->execute([$from,$to]);$tot=$s->fetch();
$s=$pdo->prepare("SELECT b.billing_period,COUNT(*) bill_count,SUM(b.consumption) usage,SUM(b.total_amount) billed,SUM(b.total_amount-b.balance) collected FROM bills b WHERE DATE(b.created_at) BETWEEN ? AND ? GROUP BY b.billing_period ORDER BY b.billing_period DESC");$s->execute([$from,$to]);$rows=$s->fetchAll();$pageTitle='Reports and analytics';require 'includes/header.php';
?>
<div class="panel"><div class="panel-head"><h3>Report period</h3></div><form method="get" class="filter-form"><div><label>From</label><input type="date" name="from" value="<?=e($from)?>"></div><div><label>To</label><input type="date" name="to" value="<?=e($to)?>"></div><button class="btn primary">Apply filters</button><button class="btn" type="button" onclick="window.print()">Print report</button></form></div>
<div class="stats-grid"><div class="stat-card"><span>Bills generated</span><strong><?=$tot['bills']?></strong></div><div class="stat-card"><span>Total billed</span><strong><?=money($tot['billed'])?></strong></div><div class="stat-card"><span>Collected</span><strong><?=money($tot['collected'])?></strong></div><div class="stat-card"><span>Outstanding</span><strong><?=money($tot['outstanding'])?></strong></div></div>
<div class="panel"><div class="panel-head"><h3>Billing summary</h3><span class="muted"><?=e($from)?> to <?=e($to)?></span></div><table><thead><tr><th>Billing period</th><th>Number of bills</th><th>Consumption</th><th>Amount billed</th><th>Collected</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['billing_period'])?></td><td><?=$r['bill_count']?></td><td><?=number_format($r['usage'],2)?> m³</td><td><?=money($r['billed'])?></td><td><?=money($r['collected'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">No billing data for this period.</td></tr><?php endif;?></tbody></table></div>
<?php require 'includes/footer.php';?>
